arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_df6eca0200244b94ad3667fc2d262147.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

<!-- Step Indicator Bar -->
<nav class="step-indicator" aria-label="Application steps">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <button class="step-item @stepClass"
                disabled="@(!IsStepClickable(stepIndex))"
                @onclick="() => GoToStep(stepIndex)">
            <span class="step-number">
                @if (stepIndex < CurrentStep)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </button>
    }
</nav>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="error-message" role="alert">@ErrorMessage</div>
}

<!-- Step 1: Personal Info -->
@if (CurrentStep == 0)
{
    <section class="form-step">
        <h2>Personal Information</h2>
        <div class="form-group">
            <label for="fullName">Full Name *</label>
            <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" placeholder="Enter your full name" />
        </div>
        <div class="form-group">
            <label for="email">Email *</label>
            <input id="email" type="email" @bind="Email" @bind:event="oninput" placeholder="Enter your email" />
        </div>
        <div class="form-group">
            <label for="phone">Phone *</label>
            <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" placeholder="Enter your phone number" />
        </div>
        <div class="form-group">
            <label for="address">Address *</label>
            <input id="address" type="text" @bind="Address" @bind:event="oninput" placeholder="Enter your address" />
        </div>
        <div class="form-buttons">
            <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@IsProcessing">
                @if (IsProcessing) { <span>Validating...</span> } else { <span>Next</span> }
            </button>
        </div>
    </section>
}

<!-- Step 2: Work History -->
@if (CurrentStep == 1)
{
    <section class="form-step">
        <h2>Work History</h2>
        @for (int i = 0; i < WorkEntries.Count; i++)
        {
            var index = i;
            <div class="work-entry">
                <h3>Position @(index + 1)</h3>
                @if (WorkEntries.Count > 1)
                {
                    <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                }
                <div class="form-group">
                    <label>Company Name *</label>
                    <input type="text" value="@WorkEntries[index].Company"
                           @onchange="(e) => UpdateWorkEntry(index, company: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Job Title *</label>
                    <input type="text" value="@WorkEntries[index].Title"
                           @onchange="(e) => UpdateWorkEntry(index, title: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Start Date *</label>
                    <input type="date" value="@WorkEntries[index].StartDate.ToString("yyyy-MM-dd")"
                           @onchange="(e) => UpdateWorkEntry(index, startDate: e.Value?.ToString())" />
                </div>
                <div class="form-group form-check">
                    <label>
                        <input type="checkbox" checked="@WorkEntries[index].IsCurrent"
                               @onchange="(e) => UpdateWorkEntry(index, isCurrent: (bool?)e.Value)" />
                        Currently working here
                    </label>
                </div>
                @if (!WorkEntries[index].IsCurrent)
                {
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" value="@(WorkEntries[index].EndDate?.ToString("yyyy-MM-dd") ?? "")"
                               @onchange="(e) => UpdateWorkEntry(index, endDate: e.Value?.ToString())" />
                    </div>
                }
                <div class="form-group">
                    <label>Description *</label>
                    <textarea value="@WorkEntries[index].Description"
                              @onchange="(e) => UpdateWorkEntry(index, description: e.Value?.ToString())"></textarea>
                </div>
            </div>
        }
        <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
        </div>
    </section>
}

<!-- Step 3: References -->
@if (CurrentStep == 2)
{
    <section class="form-step">
        <h2>References</h2>
        @for (int i = 0; i < References.Count; i++)
        {
            var index = i;
            <div class="reference-entry">
                <h3>Reference @(index + 1)</h3>
                @if (References.Count > 2)
                {
                    <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                }
                <div class="form-group">
                    <label>Name *</label>
                    <input type="text" value="@References[index].Name"
                           @onchange="(e) => UpdateReference(index, name: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" value="@References[index].Relationship"
                           @onchange="(e) => UpdateReference(index, relationship: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@References[index].Email"
                           @onchange="(e) => UpdateReference(index, email: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="text" value="@References[index].Phone"
                           @onchange="(e) => UpdateReference(index, phone: e.Value?.ToString())" />
                </div>
            </div>
        }
        @if (References.Count < 3)
        {
            <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextFromReferences">Next</button>
        </div>
    </section>
}

<!-- Step 4: Cover Letter -->
@if (CurrentStep == 3)
{
    <section class="form-step">
        <h2>Cover Letter</h2>
