        </div>
        <div class="form-group">
            <label for="email">Email *</label>
            <input id="email" type="email" @bind="Email" @bind:event="oninput" placeholder="Enter your email" />
        </div>
        <div class="form-group">
            <label for="phone">Phone *</label>
            <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" placeholder="Enter your phone number" />
        </div>
        <div class="form-group">
            <label for="address">Address *</label>
            <input id="address" type="text" @bind="Address" @bind:event="oninput" placeholder="Enter your address" />
        </div>
        <div class="form-buttons">
            <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@IsProcessing">
                @if (IsProcessing) { <span>Validating...</span> } else { <span>Next</span> }
            </button>
        </div>
    </section>
}

<!-- Step 2: Work History -->
@if (CurrentStep == 1)
{
    <section class="form-step">
        <h2>Work History</h2>
        @for (int i = 0; i < WorkEntries.Count; i++)
        {
            var index = i;
            <div class="work-entry">
                <h3>Position @(index + 1)</h3>
                @if (WorkEntries.Count > 1)
                {
                    <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                }
                <div class="form-group">
                    <label>Company Name *</label>
                    <input type="text" value="@WorkEntries[index].Company"
                           @onchange="(e) => UpdateWorkEntry(index, company: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Job Title *</label>
                    <input type="text" value="@WorkEntries[index].Title"
                           @onchange="(e) => UpdateWorkEntry(index, title: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Start Date *</label>
                    <input type="date" value="@WorkEntries[index].StartDate.ToString("yyyy-MM-dd")"
                           @onchange="(e) => UpdateWorkEntry(index, startDate: e.Value?.ToString())" />
                </div>
                <div class="form-group form-check">
                    <label>
                        <input type="checkbox" checked="@WorkEntries[index].IsCurrent"
                               @onchange="(e) => UpdateWorkEntry(index, isCurrent: (bool?)e.Value)" />
                        Currently working here
                    </label>
                </div>
                @if (!WorkEntries[index].IsCurrent)
                {
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" value="@(WorkEntries[index].EndDate?.ToString("yyyy-MM-dd") ?? "")"
                               @onchange="(e) => UpdateWorkEntry(index, endDate: e.Value?.ToString())" />
                    </div>
                }
                <div class="form-group">
                    <label>Description *</label>
