+@page "/apply"
+@rendermode InteractiveServer
+@using sv_df6eca0200244b94ad3667fc2d262147.Services
+@inject IApplicationService ApplicationService
+
+<PageTitle>Job Application</PageTitle>
+
+<h1>Job Application</h1>
+
+<!-- Step Indicator Bar -->
+<nav class="step-indicator" aria-label="Application steps">
+    @for (int i = 0; i < StepNames.Length; i++)
+    {
+        var stepIndex = i;
+        var stepClass = GetStepClass(stepIndex);
+        <button class="step-item @stepClass"
+                disabled="@(!IsStepClickable(stepIndex))"
+                @onclick="() => GoToStep(stepIndex)">
+            <span class="step-number">
+                @if (stepIndex < CurrentStep)
+                {
+                    <span class="checkmark">&#10003;</span>
+                }
+                else
+                {
+                    @(stepIndex + 1)
+                }
+            </span>
+            <span class="step-label">@StepNames[stepIndex]</span>
+        </button>
+    }
+</nav>
+
+@if (!string.IsNullOrEmpty(ErrorMessage))
+{
+    <div class="error-message" role="alert">@ErrorMessage</div>
+}
+
+<!-- Step 1: Personal Info -->
+@if (CurrentStep == 0)
+{
+    <section class="form-step">
+        <h2>Personal Information</h2>
+        <div class="form-group">
+            <label for="fullName">Full Name *</label>
+            <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" placeholder="Enter your full name" />
+        </div>
+        <div class="form-group">
+            <label for="email">Email *</label>
+            <input id="email" type="email" @bind="Email" @bind:event="oninput" placeholder="Enter your email" />
+        </div>
+        <div class="form-group">
+            <label for="phone">Phone *</label>
+            <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" placeholder="Enter your phone number" />
+        </div>
+        <div class="form-group">
+            <label for="address">Address *</label>
+            <input id="address" type="text" @bind="Address" @bind:event="oninput" placeholder="Enter your address" />
+        </div>
+        <div class="form-buttons">
+            <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@IsProcessing">
+                @if (IsProcessing) { <span>Validating...</span> } else { <span>Next</span> }
+            </button>
+        </div>
+    </section>
+}
+
+<!-- Step 2: Work History -->
+@if (CurrentStep == 1)
+{
+    <section class="form-step">
+        <h2>Work History</h2>
+        @for (int i = 0; i < WorkEntries.Count; i++)
+        {
+            var index = i;
+            <div class="work-entry">
+                <h3>Position @(index + 1)</h3>
+                @if (WorkEntries.Count > 1)
+                {
+                    <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
+                }
+                <div class="form-group">
+                    <label>Company Name *</label>
+                    <input type="text" value="@WorkEntries[index].Company"
+                           @onchange="(e) => UpdateWorkEntry(index, company: e.Value?.ToString())" />
+                </div>
+                <div class="form-group">
+                    <label>Job Title *</label>
+                    <input type="text" value="@WorkEntries[index].Title"
+                           @onchange="(e) => UpdateWorkEntry(index, title: e.Value?.ToString())" />
+                </div>
+                <div class="form-group">
+                    <label>Start Date *</label>
+                    <input type="date" value="@WorkEntries[index].StartDate.ToString("yyyy-MM-dd")"
+                           @onchange="(e) => UpdateWorkEntry(index, startDate: e.Value?.ToString())" />
+                </div>
+                <div class="form-group form-check">
+                    <label>
+                        <input type="checkbox" checked="@WorkEntries[index].IsCurrent"
+                               @onchange="(e) => UpdateWorkEntry(index, isCurrent: (bool?)e.Value)" />
+                        Currently working here
+                    </label>
+                </div>
+                @if (!WorkEntries[index].IsCurrent)
+                {
+                    <div class="form-group">
+                        <label>End Date</label>
+                        <input type="date" value="@(WorkEntries[index].EndDate?.ToString("yyyy-MM-dd") ?? "")"
+                               @onchange="(e) => UpdateWorkEntry(index, endDate: e.Value?.ToString())" />
+                    </div>
+                }
+                <div class="form-group">
+                    <label>Description *</label>
+                    <textarea value="@WorkEntries[index].Description"
+                              @onchange="(e) => UpdateWorkEntry(index, description: e.Value?.ToString())"></textarea>
+                </div>
+            </div>
+        }
+        <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
+        <div class="form-buttons">
+            <button class="btn-back" @onclick="PreviousStep">Back</button>
+            <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
+        </div>
+    </section>
+}
+
+<!-- Step 3: References -->
+@if (CurrentStep == 2)
+{
+    <section class="form-step">
+        <h2>References</h2>
+        @for (int i = 0; i < References.Count; i++)
+        {
+            var index = i;
+            <div class="reference-entry">
+                <h3>Reference @(index + 1)</h3>
+                @if (References.Count > 2)
+                {
+                    <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
+                }
+                <div class="form-group">
+                    <label>Name *</label>
+                    <input type="text" value="@References[index].Name"
+                           @onchange="(e) => UpdateReference(index, name: e.Value?.ToString())" />
+                </div>
+                <div class="form-group">
+                    <label>Relationship *</label>
+                    <input type="text" value="@References[index].Relationship"
+                           @onchange="(e) => UpdateReference(index, relationship: e.Value?.ToString())" />
+                </div>
+                <div class="form-group">
+                    <label>Email *</label>
+                    <input type="email" value="@References[index].Email"
+                           @onchange="(e) => UpdateReference(index, email: e.Value?.ToString())" />
+                </div>
+                <div class="form-group">
+                    <label>Phone *</label>
+                    <input type="text" value="@References[index].Phone"
+                           @onchange="(e) => UpdateReference(index, phone: e.Value?.ToString())" />
+                </div>
+            </div>
+        }
+        @if (References.Count < 3)
+        {
+            <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
+        }
+        <div class="form-buttons">
+            <button class="btn-back" @onclick="PreviousStep">Back</button>
+            <button class="btn-next" @onclick="NextFromReferences">Next</button>
+        </div>
+    </section>
+}
+
+<!-- Step 4: Cover Letter -->
+@if (CurrentStep == 3)
+{
+    <section class="form-step">
+        <h2>Cover Letter</h2>
+        <div class="form-group">
+            <label for="coverLetter">Write your cover letter</label>
+            <textarea id="coverLetter" class="cover-letter-input" @bind="CoverLetter" @bind:event="oninput"
+                      maxlength="2000" placeholder="Tell us why you're a great fit for this role..."></textarea>
+            <div class="character-count">@CoverLetter.Length / 2000 characters</div>
+        </div>
+        <div class="form-buttons">
+            <button class="btn-back" @onclick="PreviousStep">Back</button>
+            <button class="btn-next" @onclick="NextFromCoverLetter">Next</button>
+        </div>
+    </section>
+}
+
+<!-- Step 5: Review & Submit -->
+@if (CurrentStep == 4)
+{
+    @if (IsSubmitted)
+    {
+        <section class="form-step confirmation">
+            <h2>Application Submitted!</h2>
+            <p class="confirmation-message">Thank you for your application. Your application ID is: <strong>@ApplicationId</strong></p>
+        </section>
+    }
+    else
+    {
+        <section class="form-step">
+            <h2>Review & Submit</h2>
+
+            <div class="review-section">
+                <div class="review-header">
+                    <h3>Personal Information</h3>
+                    <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
+                </div>
+                <dl>
+                    <dt>Full Name</dt><dd>@FullName</dd>
+                    <dt>Email</dt><dd>@Email</dd>
+                    <dt>Phone</dt><dd>@Phone</dd>
+                    <dt>Address</dt><dd>@Address</dd>
+                </dl>
+            </div>
+
+            <div class="review-section">
+                <div class="review-header">
+                    <h3>Work History</h3>
+                    <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
+                </div>
+                @foreach (var entry in WorkEntries)
+                {
+                    <div class="review-work-entry">
+                        <p><strong>@entry.Title</strong> at @entry.Company</p>
+                        <p>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</p>
+                        <p>@entry.Description</p>
+                    </div>
+                }
+            </div>
+
+            <div class="review-section">
+                <div class="review-header">
+                    <h3>References</h3>
+                    <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
+                </div>
+                @foreach (var reference in References)
+                {
+                    <div class="review-reference">
+                        <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
+                        <p>@reference.Email | @reference.Phone</p>
+                    </div>
+                }
+            </div>
+
+            <div class="review-section">
+                <div class="review-header">
+                    <h3>Cover Letter</h3>
+                    <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
+                </div>
+                <p class="cover-letter-preview">@CoverLetter</p>
+            </div>
+
+            <div class="form-buttons">
+                <button class="btn-back" @onclick="PreviousStep">Back</button>
+                <button class="btn-submit" @onclick="SubmitApplication" disabled="@IsProcessing">
+                    @if (IsProcessing) { <span>Submitting...</span> } else { <span>Submit Application</span> }
+                </button>
+            </div>
+        </section>
+    }
+}
+
+@code {
+    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+
+    private int CurrentStep { get; set; } = 0;
+    private string ErrorMessage { get; set; } = string.Empty;
+    private bool IsProcessing { get; set; }
+    private bool IsSubmitted { get; set; }
+    private int ApplicationId { get; set; }
+
+    // Step 1 fields
+    private string FullName { get; set; } = string.Empty;
+    private string Email { get; set; } = string.Empty;
+    private string Phone { get; set; } = string.Empty;
+    private string Address { get; set; } = string.Empty;
+
+    // Step 2 fields
+    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };
+
+    // Step 3 fields
+    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4 fields
+    private string CoverLetter { get; set; } = string.Empty;
+
+    private string GetStepClass(int step)
+    {
+        if (step == CurrentStep) return "active";
+        if (step < CurrentStep) return "completed";
+        return "dimmed";
+    }
+
+    private bool IsStepClickable(int step)
+    {
+        return step < CurrentStep;
+    }
+
+    private void GoToStep(int step)
+    {
+        if (step < CurrentStep)
+        {
+            CurrentStep = step;
+            ErrorMessage = string.Empty;
+        }
+    }
+
+    private void PreviousStep()
+    {
+        if (CurrentStep > 0)
+        {
+            CurrentStep--;
+            ErrorMessage = string.Empty;
+        }
+    }
+
+    private async Task NextFromPersonalInfo()
+    {
+        ErrorMessage = string.Empty;
+
+        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
+            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
+        {
+            ErrorMessage = "All fields are required.";
+            return;
+        }
+
+        IsProcessing = true;
+        try
+        {
+            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
+            if (!emailValid)
+            {
+                ErrorMessage = "Please enter a valid email address.";
+                return;
+            }
+            CurrentStep = 1;
+        }
+        finally
+        {
+            IsProcessing = false;
+        }
+    }
+
+    private void NextFromWorkHistory()
+    {
+        ErrorMessage = string.Empty;
+
+        foreach (var entry in WorkEntries)
+        {
+            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
+                string.IsNullOrWhiteSpace(entry.Description) || entry.StartDate == default)
+            {
+                ErrorMessage = "Please fill in all required fields for each work entry.";
+                return;
+            }
+        }
+
+        CurrentStep = 2;
+    }
+
+    private void NextFromReferences()
+    {
+        ErrorMessage = string.Empty;
+
+        foreach (var r in References)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
+                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+            {
+                ErrorMessage = "Please fill in all required fields for each reference.";
+                return;
+            }
+        }
+
+        CurrentStep = 3;
+    }
+
+    private void NextFromCoverLetter()
+    {
+        ErrorMessage = string.Empty;
+
+        if (string.IsNullOrWhiteSpace(CoverLetter))
+        {
+            ErrorMessage = "Please write a cover letter.";
+            return;
+        }
+
+        CurrentStep = 4;
+    }
+
+    private async Task SubmitApplication()
+    {
+        IsProcessing = true;
+        ErrorMessage = string.Empty;
+
+        try
+        {
+            var personal = new PersonalInfo(FullName, Email, Phone, Address);
+            var workHistory = new WorkHistory(WorkEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
+            var references = References.Select(r =>
+                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+
+            var application = new JobApplication(personal, workHistory, references, CoverLetter);
+            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
+            IsSubmitted = true;
+        }
+        catch (Exception ex)
+        {
+            ErrorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            IsProcessing = false;
+        }
+    }
+
+    // Work entry helpers
+    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());
+
+    private void RemoveWorkEntry(int index)
+    {
+        if (WorkEntries.Count > 1)
+            WorkEntries.RemoveAt(index);
+    }
+
+    private void UpdateWorkEntry(int index, string? company = null, string? title = null,
+        string? startDate = null, string? endDate = null, string? description = null, bool? isCurrent = null)
+    {
+        var entry = WorkEntries[index];
+        if (company != null) entry.Company = company;
+        if (title != null) entry.Title = title;
+        if (startDate != null && DateTime.TryParse(startDate, out var sd)) entry.StartDate = sd;
+        if (endDate != null && DateTime.TryParse(endDate, out var ed)) entry.EndDate = ed;
+        if (description != null) entry.Description = description;
+        if (isCurrent.HasValue)
+        {
+            entry.IsCurrent = isCurrent.Value;
+            if (isCurrent.Value) entry.EndDate = null;
+        }
+    }
+
+    // Reference helpers
+    private void AddReference()
+    {
+        if (References.Count < 3)
+            References.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (References.Count > 2)
+            References.RemoveAt(index);
+    }
+
+    private void UpdateReference(int index, string? name = null, string? relationship = null,
+        string? email = null, string? phone = null)
+    {
+        var r = References[index];
+        if (name != null) r.Name = name;
+        if (relationship != null) r.Relationship = relationship;
+        if (email != null) r.Email = email;
+        if (phone != null) r.Phone = phone;
+    }
+
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = string.Empty;
+        public string Title { get; set; } = string.Empty;
+        public DateTime StartDate { get; set; } = DateTime.Today;
+        public DateTime? EndDate { get; set; }
+        public string Description { get; set; } = string.Empty;
+        public bool IsCurrent { get; set; }
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = string.Empty;
+        public string Relationship { get; set; } = string.Empty;
+        public string Email { get; set; } = string.Empty;
+        public string Phone { get; set; } = string.Empty;
+    }
+}
