arguments.file_text:
.step-indicator {
    display: flex;
    justify-content: space-between;
    margin-bottom: 2rem;
    padding: 1rem 0;
    border-bottom: 1px solid #e0e0e0;
    gap: 0.5rem;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    flex: 1;
    transition: opacity 0.2s;
}

.step-item:disabled {
    cursor: default;
}

.step-item.dimmed {
    opacity: 0.4;
}

.step-item.active .step-number {
    background-color: #0d6efd;
    color: white;
}

.step-item.completed .step-number {
    background-color: #198754;
    color: white;
}

.step-number {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    background-color: #e0e0e0;
    font-weight: bold;
    font-size: 0.875rem;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    font-weight: 500;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 700;
}

.form-step {
    max-width: 700px;
    margin: 0 auto;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

.form-group textarea {
    min-height: 100px;
    resize: vertical;
}

.cover-letter-input {
    min-height: 250px !important;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

.form-check label {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal;
}

.form-check input[type="checkbox"] {
    width: auto;
}

.form-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #e0e0e0;
}

.btn-next, .btn-submit {
    background-color: #0d6efd;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
    margin-left: auto;
}

.btn-next:hover, .btn-submit:hover {
    background-color: #0b5ed7;
}

.btn-next:disabled, .btn-submit:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-back {
    background-color: #6c757d;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
}

.btn-back:hover {
    background-color: #5c636a;
}

.btn-add {
    background-color: #198754;
    color: white;
    border: none;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    margin-top: 0.5rem;
}

.btn-add:hover {
    background-color: #157347;
}

.btn-remove {
    background-color: #dc3545;
    color: white;
    border: none;
    padding: 0.3rem 0.75rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.8rem;
    float: right;
}

.btn-remove:hover {
    background-color: #bb2d3b;
}

.btn-edit {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
}

.btn-edit:hover {
    color: #0b5ed7;
}

.work-entry, .reference-entry {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    overflow: hidden;
}

.work-entry h3, .reference-entry h3 {
    margin-top: 0;
    margin-bottom: 1rem;
}

.error-message {
    background-color: #f8d7da;
    color: #842029;
